{"command":"python3 - << 'PY'
import itertools

def nae_satisfiable(num_vars, clauses):
    # vars indexed 1..num_vars
    for assign in itertools.product([False, True], repeat=num_vars):
        ok=True
        for clause in clauses:
            vals=[assign[abs(lit)-1] if lit>0 else not assign[abs(lit)-1] for lit in clause]
            # NAE: not all equal
            if vals[0]==vals[1]==vals[2]:
                ok=False
                break
        if ok:
            return True
    return False

variables = [1,2,3]
all_clauses = []
for lits in itertools.product([1,-1,2,-2,3,-3], repeat=3):
    # ensure distinct variables
    if len({abs(l) for l in lits})==3:
        all_clauses.append(list(lits))

# search for unsat set up to size 4
for r in range(1,5):
    for combo in itertools.combinations(all_clauses, r):
        if not nae_satisfiable(3, combo):
            print('Found unsat set size', r)
            for c in combo:
                print(c)
            raise SystemExit
print('none found up to size 4')
