{"command":"python3 - << 'PY'
import itertools, sys

orig_vars = ['a','b','c']
new_vars = ['y','z']
all_vars = orig_vars + new_vars

def eval_literal(lit, assign):
    var = lit[1:]
    val = assign[var]
    return val if lit[0]=='+' else (not val)

def clause_satisfied(clause, assign):
    vals = [eval_literal(lit, assign) for lit in clause]
    # NAE satisfied if not all equal
    return not (vals[0]==vals[1]==vals[2])

# generate possible literals: +a, -a, etc.
lit_options = []
for v in all_vars:
    lit_options.append('+'+v)
    lit_options.append('-'+v)

# generate all possible clauses (distinct vars)
clauses = []
for combo in itertools.combinations(lit_options,3):
    vars_in = {lit[1:] for lit in combo}
    if len(vars_in)==3:
        clauses.append(list(combo))

# search for up to 3 clauses using up to 2 new vars
max_clauses = 3
for num_clauses in range(1, max_clauses+1):
    for selected in itertools.combinations(clauses, num_clauses):
        # test gadget
        good = True
        for orig_assign in itertools.product([False, True], repeat=3):
            orig = dict(zip(orig_vars, orig_assign))
            # determine if original clause satisfied (a or b or c)
            orig_sat = any(orig_assign)
            # need existence of assignment to new vars making all clauses satisfied iff orig_sat
            exists = False
            for new_assign in itertools.product([False, True], repeat=len(new_vars)):
                assign = orig.copy()
                assign.update(dict(zip(new_vars, new_assign)))
                if all(clause_satisfied(cl, assign) for cl in selected):
                    exists = True
                    break
            if exists != orig_sat:
                good = False
                break
        if good:
            print('Found gadget with', num_clauses, 'clauses')
            for cl in selected:
                print(cl)
            sys.exit()
print('none found')
PY"}

