{"command":"python3 - << 'PY'
import itertools, sys

orig_vars = ['a','b','c']
new_vars = ['y']
all_vars = orig_vars + new_vars

def eval_lit(lit, assign):
    var = lit[1:]
    val = assign[var]
    return val if lit[0]=='+' else (not val)

def clause_satisfied(clause, assign):
    vals = [eval_lit(l, assign) for l in clause]
    return not (vals[0]==vals[1]==vals[2])

def gadget_ok(clauses):
    # for each assignment to original vars, there exists assignment to new vars s.t. all clauses satisfied iff original clause satisfied
    for orig_assign in itertools.product([False, True], repeat=3):
        orig = dict(zip(orig_vars, orig_assign))
        orig_sat = any(orig_assign)  # a or b or c
        # check existence of new assignment
        exists = False
        for new_assign in itertools.product([False, True], repeat=len(new_vars)):
            assign = orig.copy()
            assign.update(dict(zip(new_vars, new_assign)))
            if all(clause_satisfied(cl, assign) for cl in clauses):
                exists = True
                break
        if exists != orig_sat:
            return False
    return True

# generate possible literals
lit_options = []
for v in all_vars:
    lit_options.append('+'+v)
    lit_options.append('-'+v)

# generate all possible clauses (distinct vars)
all_clauses = []
for combo in itertools.combinations(lit_options,3):
    if len({lit[1:] for lit in combo})==3:
        all_clauses.append(list(combo))

# search for small sets of clauses up to size 3
for size in range(1,4):
    for sel in itertools.combinations(all_clauses, size):
        if gadget_ok(sel):
            print('Found gadget size', size)
            for cl in sel:
                print(cl)
            sys.exit()
print('none found')
