import itertools, random, sys

def sat_3sat(num_vars, clauses):
    for assign in itertools.product([False,True], repeat=num_vars):
        ok=True
        for cl in clauses:
            if not any((assign[abs(l)-1] if l>0 else not assign[abs(l)-1]) for l in cl):
                ok=False; break
        if ok:
            return True
    return False

def sat_nae(num_vars, clauses):
    for assign in itertools.product([False,True], repeat=num_vars):
        ok=True
        for cl in clauses:
            vals=[assign[abs(l)-1] if l>0 else not assign[abs(l)-1] for l in cl]
            if vals[0]==vals[1]==vals[2]:
                ok=False; break
        if ok:
            return True
    return False

def reduce_instance(inst):
    m=inst['num_vars']
    clauses=inst['clauses']
    new_clauses=[]
    # new variable per original clause
    for i,cl in enumerate(clauses):
        y = m + i + 1
        # clause1: l1,l2,y
        new_clauses.append([cl[0], cl[1], y])
        # clause2: l3,-y,-y
        new_clauses.append([cl[2], -y, -y])
    return {'num_vars': m+len(clauses), 'clauses': new_clauses}

# test random small
for vars in range(1,5):
    for _ in range(200):
        # generate random 3SAT instance with maybe 0-3 clauses
        num_clauses=random.randint(0,3)
        clauses=[]
        for _ in range(num_clauses):
            # pick 3 distinct vars
            vars_sel=random.sample(range(1,vars+1),3)
            clause=[]
            for v in vars_sel:
                lit=v if random.choice([True,False]) else -v
                clause.append(lit)
            clauses.append(clause)
        inst={'num_vars':vars,'clauses':clauses}
        sat3=sat_3sat(vars,clauses)
        red=reduce_instance(inst)
        satnae=sat_nae(red['num_vars'], red['clauses'])
        if sat3!=satnae:
            print('counterexample')
            print(inst)
            print('red',red)
            sys.exit()
print('all ok')
