    for combo in itertools.combinations(literals,3):
        if len({abs(l) for l in combo})==3:
            all_clauses.append(list(combo))
    # search for set of clauses up to size 3 that enforce u = not y (i.e., for all assignments, clause set satisfiable iff u == not y)
    for size in range(1,4):
