                sat=nae_sat(assign, sel)
                condition = (assign[1]== (not assign[0]))  # u == not y, index 0:y,1:u
                if sat!=condition:
                    ok=False; break
            if ok:
                print('Found gadget', sel)
                return
    print('none')

